SELECT code, nom, prenom, categorie, count(code_pers) as nombreEmpruntEffectue FROM `livre_emprunt` le left join (`adherent` a left join `personne` p on a.id_pers = p.id) on le.code_pers = a.id_adh where id_adh is not null and (le.date_emprunt <= '2024-12-31' and le.date_emprunt >= '2024-01-01') group by code_pers order by nombreEmpruntEffectue desc

